import React,{useRef} from 'react';
import {Video,ResizeMode} from 'expo-av';
import {View,Button} from 'react-native';
export default function V(){
  const ref=useRef<Video>(null);
  return(<View style={{flex:1}}><Video ref={ref} source={{uri:'{{video_url}}'}} useNativeControls resizeMode={ResizeMode.CONTAIN} style={{flex:1}}/><Button title='Play' onPress={()=>ref.current?.playAsync()}/></View>);}
